// Write the date of the backup you want to download, in YYYY-MM-DD format.
// If you leave it empty, it downloads TODAY's.
const DATE = '';

const date = DATE.trim()
  || DateTime.now().setZone('America/Costa_Rica').toFormat('yyyy-MM-dd');

if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  throw new Error(`Invalid date: "${date}". It has to be YYYY-MM-DD, for example 2026-09-10.`);
}

return [{ json: { date, object_key: `sends/sends_${date}.json` } }];
